import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"塞思·斯科菲尔德","description":"","frontmatter":{"title":"塞思·斯科菲尔德","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/塞思·斯科菲尔德.md","filePath":"04_people/塞思·斯科菲尔德.md"}'),o={name:"04_people/塞思·斯科菲尔德.md"};function i(n,a,s,_,h,p){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="塞思·斯科菲尔德" tabindex="-1">塞思·斯科菲尔德 <a class="header-anchor" href="#塞思·斯科菲尔德" aria-label="Permalink to &quot;塞思·斯科菲尔德&quot;">​</a></h1><ul><li><strong>角色职位</strong>：全美航空（USAir）CEO</li><li><strong>与巴菲特关系</strong>：伯克希尔·哈撒韦曾投资或涉及全美航空相关交易</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>塞思·斯科菲尔德曾担任全美航空（USAir，现为美国航空一部分）CEO。全美航空是美国主要的航空公司之一，总部位于匹兹堡，在美国东海岸和加勒比海地区拥有广泛航线网络。斯科菲尔德作为 CEO，主导了这家航空公司在1980年代末至1990年代初的运营与战略决策。</p><p>在斯科菲尔德任期内，全美航空面临航空业特有的挑战，包括高燃油成本、严格的监管环境以及激烈的价格竞争。与此同时，美国航空业经历了多轮整合，航空公司之间的合并与收购频繁发生。斯科菲尔德在这一复杂环境中努力维持公司的竞争力和财务健康。</p><p>巴菲特对航空股的态度在历史上经历了显著变化。1990年代初期，巴菲特曾对包括全美航空在内的多家航空公司表达过兴趣，但随后航空业的高成本结构和周期性特征令其多次公开&quot;不看好&quot;航空股。斯科菲尔德时代的全美航空，正处于航空公司试图从行业困境中突围的关键阶段。巴菲特最终在后来才真正大举投资航空股（2016年买入航空公司股票），而斯科菲尔德时代的全美航空更多是伯克希尔关注过但未深入介入的一段历史注脚。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>CEO 任期</strong>：担任全美航空 CEO，主导公司在航空业激烈竞争中的战略运营</li><li><strong>行业调整期</strong>：面对航空业高成本和低利润挑战，探索重组与转型路径</li><li><strong>后续发展</strong>：全美航空后来与美国航空等合并，斯科菲尔德的任期内为公司的早期整合奠定了基础</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=塞思·斯科菲尔德在1994年股东信中的原话">1994年：完整翻译|/01_letters/1994年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
